"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, key: str) -> object:
    """Return a field value, with missing fields behaving as legacy empty strings."""
    if row is None:
        return ""
    value = row.get(key, "")
    return "" if value is None else value


def _numeric(value: object) -> Decimal:
    """Apply the required legacy numeric coercion for empty values."""
    if value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        # Source numeric fields are stored as NUMBER values; this fallback keeps
        # absent/non-materialized values equivalent to the legacy empty value.
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: object,
    output_column: str,
) -> object:
    """Perform an ordered legacy LOOKUP, excluding soft-deleted rows."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order record and return all applicable rule failures in file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            discount = _numeric(_value(record, "DISC_PCT"))
            if not (discount >= Decimal(0) and discount <= Decimal(100)):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        if event == "UPDATE":
            discount = _numeric(_value(record, "DISC_PCT"))
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if discount > Decimal(20) and owner_role != "MGR" and owner_role != "ADMIN":
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

            if (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            ):
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_numeric(_value(record, "QTY")) > Decimal(0)):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
